//-------------------------------------------------

// Newtons Egg:  https://www.2dcurves.com/cubic/cubicn.html
float Egg1 (in vec2 p, in float a, in float b) 
{
  // 4*x² - (y²-2) * (y-0.5);   // Newtons Egg
  return 4.0*p.x*p.x - (p.y*p.y-a) * (p.y-b) ;
}

//-------------------------------------------------
// https://www.mathematische-basteleien.de/eggcurves.htm
// blue egg shape: t2(x)
float Egg2 (in vec2 p, in float a, in float b) 
{
  float x = p.y*a;
  float y = p.x*b;
  return x*x/9. +y*y/4. * (1./(1.0 -0.12*x)) -1.0;
}  

//-------------------------------------------------
void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
  vec2 p = (2.5*fragCoord-iResolution.xy) / iResolution.y-0.5;
  p.y += 0.2 + 2.6 * iMouse.y / iResolution.y;

  //~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
//float d = Egg1 (p, 0.5, 2.0 + 0.2*cos(iTime));
  //~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
  float d = Egg2 (p, 3.5, 3.5 + 0.2*cos(iTime));
  //~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
  vec3 
  colIn  = vec3(0.9, 0.6, 0.3),
  colOut = vec3(0.6, 0.8, 1.0),
  colFig = vec3(1, 1, 1),
  col = (d > 0.0) ? colIn : colOut;
  col *= 1.0 - exp(-6.0*abs(d));
  col *= 0.8 + 0.2*cos(120.0*d);
  col = mix (col, colFig, 1.0 - smoothstep(0.0, 0.1, abs(d)) );
  fragColor = vec4(col, 1.0);
}
